from lib import *
S = SS('p12')
steps = [
    step("先弄清会话票据什么时候可复用(第 1 次连接取会话、第 2 次连接带上它)。客户端在收到响应后立刻取会话:不论服务器怎么关连接,第 2 次都复用成功(True)。客户端一直读到 EOF 才取会话:服务器直接关 TCP、不发 close_notify 时复用失败(False);服务器先发 close_notify 再关时仍然成功(True)。也就是说,连接被不干净地关掉,这个会话就不能再用了(这是我对实测结果的解释,没有读 OpenSSL 源码)。", t=tl(S(1)), done=lidx(S(1), '先发 close_notify 再关;客户端一直读到 EOF', '直接关 TCP(不发 close_notify);客户端收到响应就立刻取会话'), mark=lidx(S(1), '直接关 TCP(不发 close_notify);客户端一直读到 EOF'), kv=KV([['立刻取会话', '总是可复用'], ['直接关 TCP + 读到 EOF', '不可复用'], ['先发 close_notify', '读到 EOF 也可复用']], ['直接关 TCP + 读到 EOF'])),
    step("一次 HTTPS 请求的时间(P-256 证书、TLS 1.3、本机回环,各 300 次的中位数):完整握手是 TCP 连接 0.089 ms + TLS 握手 0.628 ms + 请求响应 0.145 ms = 0.862 ms,握手占 73%;会话复用后 TLS 握手降到 0.528 ms,总共 0.750 ms,握手占 70%。复用 / 完整 = 0.84,客户端确认复用成功的比例 100%。这是 EC 证书的情形;握手时间没有大幅下降,因为 TLS 1.3 的复用仍然要做一次密钥交换。", t=tl(S(2)), done=lidx(S(2), '会话复用:'), mark=lidx(S(2), '完整握手:'), b=bars([['完整握手:TLS 握手 ms', 0.628, '0.628'], ['会话复用:TLS 握手 ms', 0.528, '0.528'], ['TCP 连接 ms', 0.089, '0.089'], ['请求/响应 ms', 0.145, '0.145']], 0.7, mark=[0], done=[1]), kv=KV([['完整握手', '0.862 ms,握手占 73%'], ['会话复用', '0.750 ms,握手占 70%'], ['握手耗时比', '0.84']], ['握手耗时比'])),
    step("证书的密钥类型对完整握手影响很大(服务器要签名),会话复用时则基本一样:ec256 完整 0.625 ms、复用 0.522 ms;ec384 1.012 对 0.533;rsa2048 1.094 对 0.521;rsa4096 3.993 对 0.525。服务器用 RSA-4096 时,复用能把握手从 3.993 ms 降到 0.525 ms;用 EC P-256 时只省 0.1 ms。", t=tl(S(3)), done=lidx(S(3), 'rsa4096', 'ec256'), mark=lidx(S(3), 'ec384', 'rsa2048'), b=bars([['ec256 完整 ms', 0.625, '0.625'], ['ec384 完整 ms', 1.012, '1.012'], ['rsa2048 完整 ms', 1.094, '1.094'], ['rsa4096 完整 ms', 3.993, '3.993'], ['任意证书 复用 ms', 0.525, '≈0.52']], 4, mark=[3], done=[4]), kv=KV([['rsa4096', '完整 3.993 → 复用 0.525 ms'], ['ec256', '完整 0.625 → 复用 0.522 ms'], ['复用后', '与证书类型几乎无关']], ['rsa4096'])),
    step("TLS 1.2 与 TLS 1.3(P-256,本机回环没有网络延迟,往返次数的差别看不出来):TLS 1.3 完整握手 0.591 ms,复用 0.495 ms;限制到 TLS 1.2 完整握手 0.450 ms,复用 0.155 ms。两种版本复用都成功(100%)。在回环上 TLS 1.2 的计算更便宜,复用后只要 0.155 ms;真实网络里 1.3 的好处主要是少一个往返,这一点我没有测。", t=tl(S(4)), done=lidx(S(4), 'TLS 1.3:', '限制到 TLS 1.2'), b=bars([['TLS 1.3 完整 ms', 0.591, '0.591'], ['TLS 1.3 复用 ms', 0.495, '0.495'], ['TLS 1.2 完整 ms', 0.450, '0.450'], ['TLS 1.2 复用 ms', 0.155, '0.155']], 0.6, done=[1, 3]), kv=KV([['TLS 1.3', '完整 0.591 / 复用 0.495 ms'], ['TLS 1.2', '完整 0.450 / 复用 0.155 ms'], ['往返次数', '回环里看不出']], ['往返次数'])),
    step("各个客户端库在“每个请求都新建连接”时复用 TLS 会话的情况(20 次请求,服务器记录哪些连接是复用的):requests.get 0 个;同一个 requests.Session 每次 Connection: close 0 个;aiohttp force_close=True 0 个——它们每次都完整握手(我在 urllib3 和 aiohttp 的连接代码里搜不到传递 TLS 会话的地方)。curl_cffi 的 Session 每次 Connection: close:20 个里 19 个复用(第一个没有票据可用);但每次新建 curl_cffi 会话的 curl_cffi.requests.get 是 0 个。", t=tl(S(5)), done=lidx(S(5), 'curl_cffi Session,每次'), mark=lidx(S(5), 'requests.get ×20', '同一个 requests.Session', 'aiohttp'), b=bars([['requests(20 个连接中复用)', 0, '0'], ['aiohttp', 0, '0'], ['curl_cffi Session', 19, '19'], ['curl_cffi.get(每次新会话)', 0, '0']], 20, mark=[0, 1, 3], done=[2]), kv=KV([['requests / aiohttp', '每次完整握手'], ['curl_cffi Session', '19/20 复用'], ['curl_cffi.get', '每次新建会话,不复用']], ['curl_cffi Session'])),
]
A = mkartp('p12', 12, '爬虫,TLS,会话复用,握手,session ticket,curl_cffi,requests,Python,真实验证,动画演示',
    '在本机 TLS 服务器上量握手:EC 证书的完整握手占一次 HTTPS 请求约 73%,会话复用后 TLS 握手 0.628 ms 降到 0.528 ms;RSA-4096 证书则从 3.993 ms 降到 0.525 ms;连接被不干净地关掉(没有 close_notify)后读到 EOF,会话不可复用;requests 和 aiohttp 不复用,curl_cffi 的 Session 复用 19/20。',
    '每次新建 HTTPS 连接都要做 TLS 握手。握手到底占一次请求多少时间、会话复用能省多少、你用的库会不会复用,这篇用本机的 TLS 服务器逐项量。顺带发现:一个会话票据在什么情况下会变得不可复用。',
    [('73%', '完整握手占一次小 HTTPS 请求总耗时的比例(P-256 证书、TLS 1.3、本机回环)'), ('3.993 → 0.525 ms', 'RSA-4096 证书的握手耗时:完整握手对会话复用'), ('19 / 20', 'curl_cffi Session 每个请求新建连接时复用了 TLS 会话的连接数(requests、aiohttp 都是 0)')],
    [('会话票据什么时候失效', '<p>客户端拿到的会话票据,在“连接被不干净地关掉之后又读到 EOF”时会变得不可复用:服务器直接关 TCP(没有 TLS 的 <code>close_notify</code>)、客户端读到 EOF 再取会话,第 2 次连接就复用失败;服务器先发 <code>close_notify</code>,或客户端在收到响应时就取走会话,则正常。这是实测现象,原因是我的解释,没有读 OpenSSL 的实现。</p>'),
     ('握手占多少', '<p>用 P-256 证书、TLS 1.3,在本机回环上,完整握手 0.628 ms,TCP 连接 0.089 ms,请求响应 0.145 ms,握手占 73%。会话复用把握手降到 0.528 ms(0.84 倍)。TLS 1.3 的复用仍然要做一次密钥交换,所以省得不多;没有网络往返的本机环境也会低估真实世界里握手的比例。</p>'),
     ('证书类型的影响', '<p>服务器每次完整握手都要签名,密钥类型差别很大:P-256 0.625 ms、P-384 1.012 ms、RSA-2048 1.094 ms、RSA-4096 3.993 ms。会话复用时不再需要证书签名,不管什么证书都只要约 0.52 ms。所以服务器证书越“重”,客户端复用会话的收益越大。</p>'),
     ('TLS 1.2 与 1.3', '<p>本机回环没有往返延迟,看到的只是计算量:TLS 1.2 完整握手 0.450 ms、复用 0.155 ms;TLS 1.3 完整握手 0.591 ms、复用 0.495 ms。往返次数的差别(TLS 1.3 少一个往返)要在有延迟的网络上才能体现,我没有测。</p>'),
     ('各库会不会复用', '<p>Python 的 ssl 不会自动复用会话,要手动把上一次的会话对象传给 <code>wrap_socket(session=…)</code>。在 urllib3 与 aiohttp 的连接代码里我没搜到传递会话的地方,实测它们 20 个新连接 0 个复用。<code>curl_cffi</code>(libcurl)在同一个 Session 内缓存会话票据,19/20 复用;每次新建 Session 就没有缓存了。</p>')],
    steps,
    [ENV_P + '。握手各段用 time.perf_counter 在客户端分段计时(socket.create_connection、SSLContext.wrap_socket 的握手、发送与接收);会话复用用 wrap_socket(session=…) 并检查 session_reused;完整握手与复用交替各做 200–300 次取中位数;证书用 openssl 生成(EC P-256、P-384,RSA-2048、RSA-4096,自签名,客户端不校验);服务器和客户端都是 Python 的 ssl 模块(链接的是 OpenSSL 3.6.5),服务端记录每条连接的 session_reused;证书由命令行 openssl 4.0.3 生成',
     '没有验证:真实网络里握手的往返次数对总耗时的影响(本机回环没有延迟);TLS 1.3 的 0-RTT;证书链校验的耗时(客户端关闭了校验);nginx 等真实服务器的会话缓存与票据密钥轮换;票据的有效期;为什么不干净的关闭会让会话失效的底层原因;让 requests 或 aiohttp 手动复用会话的做法'],
    'TLS 会话复用')
